// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py UTC_ARGS: --version 6
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -O2 -Wno-missing-declarations -fsanitize=array-bounds -fsanitize-trap=array-bounds -emit-llvm -o - %s | FileCheck %s

// Tests the different shapes of base expression that can be used to reach a
// 'counted_by' flexible array member or pointer, for both
// __builtin_dynamic_object_size and -fsanitize=array-bounds.
//
// The main properties being checked are:
//   - a base with side-effects is never re-evaluated to load the count. The
//     __bdos of such an expression falls back to the default (-1), while the
//     bounds check reuses the already-evaluated base.
//   - bases that are reachable without side-effects (nested pointers, array
//     subscripts, explicit dereferences) load the count from the right struct.
//   - a provably out-of-range constant index folds to zero.

#define __bdos(P) __builtin_dynamic_object_size(P, 1)

struct s {
  int count;
  int array[] __attribute__((counted_by(count)));
};

struct p {
  int count;
  int *buf __attribute__((counted_by(count)));
};

struct wrap {
  long tag;
  struct s *s;
};

enum count_enum { CE_ZERO, CE_ONE };

struct e {
  enum count_enum count;
  int array[] __attribute__((counted_by(count)));
};

struct s *get_s(void);
struct p *get_p(void);

// A call has side-effects, so __bdos can't use it to load the count.
// CHECK-LABEL: define dso_local noundef i64 @test_bdos_call_base(
// CHECK-SAME: ) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    ret i64 -1
//
unsigned long test_bdos_call_base(void) {
  return __bdos(get_s()->array);
}

// The bounds check must reuse the call's result rather than calling again.
// CHECK-LABEL: define dso_local i32 @test_index_call_base(
// CHECK-SAME: i32 noundef [[I:%.*]]) local_unnamed_addr #[[ATTR1:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[CALL:%.*]] = tail call ptr @get_s() #[[ATTR9:[0-9]+]]
// CHECK-NEXT:    [[DOTCOUNTED_BY_LOAD:%.*]] = load i32, ptr [[CALL]], align 4
// CHECK-NEXT:    [[TMP0:%.*]] = icmp ult i32 [[I]], [[DOTCOUNTED_BY_LOAD]], !nosanitize [[META6:![0-9]+]]
// CHECK-NEXT:    [[TMP1:%.*]] = icmp sgt i32 [[DOTCOUNTED_BY_LOAD]], 0, !nosanitize [[META6]]
// CHECK-NEXT:    [[TMP2:%.*]] = and i1 [[TMP1]], [[TMP0]], !nosanitize [[META6]]
// CHECK-NEXT:    br i1 [[TMP2]], label %[[CONT:.*]], label %[[TRAP:.*]], !prof [[PROF7:![0-9]+]], !nosanitize [[META6]]
// CHECK:       [[TRAP]]:
// CHECK-NEXT:    tail call void @llvm.ubsantrap(i8 18) #[[ATTR10:[0-9]+]], !nosanitize [[META6]]
// CHECK-NEXT:    unreachable, !nosanitize [[META6]]
// CHECK:       [[CONT]]:
// CHECK-NEXT:    [[ARRAY:%.*]] = getelementptr inbounds nuw i8, ptr [[CALL]], i64 4
// CHECK-NEXT:    [[IDXPROM:%.*]] = sext i32 [[I]] to i64
// CHECK-NEXT:    [[ARRAYIDX:%.*]] = getelementptr inbounds [4 x i8], ptr [[ARRAY]], i64 [[IDXPROM]]
// CHECK-NEXT:    [[TMP3:%.*]] = load i32, ptr [[ARRAYIDX]], align 4, !tbaa [[INT_TBAA8:![0-9]+]]
// CHECK-NEXT:    ret i32 [[TMP3]]
//
int test_index_call_base(int i) {
  return get_s()->array[i];
}

